1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	<meta charset="utf-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1">
6	<title>Calculator</title>
7	<style>
8	  * { box-sizing: border-box; }
9	  body {
10	    margin: 0;
11	    min-height: 100vh;
12	    display: flex;
13	    align-items: center;
14	    justify-content: center;
15	    background: #eef0f3;
16	    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
17	  }
18	  .calc {
19	    width: 300px;
20	    padding: 16px;
21	    background: #1f2329;
22	    border-radius: 16px;
23	    box-shadow: 0 10px 30px rgba(0, 0, 0, 0.25);
24	  }
25	  .display {
26	    height: 72px;
27	    margin-bottom: 12px;
28	    padding: 0 12px;
29	    display: flex;
30	    align-items: center;
31	    justify-content: flex-end;
32	    background: #111418;
33	    color: #fff;
34	    font-size: 40px;
35	    border-radius: 10px;
36	    overflow: hidden;
37	    white-space: nowrap;
38	  }
39	  .keys {
40	    display: grid;
41	    grid-template-columns: repeat(4, 1fr);
42	    gap: 8px;
43	  }
44	  button {
45	    height: 56px;
46	    border: 0;
47	    border-radius: 10px;
48	    background: #3a3f47;
49	    color: #fff;
50	    font-size: 22px;
51	    cursor: pointer;
52	  }
53	  button:active { filter: brightness(1.3); }
54	  button.op { background: #f0a030; }
55	  button.clear { background: #a5a5a5; color: #111; }
56	  button.equals { background: #3c8cf0; }
57	  button.wide { grid-column: span 2; }
58	</style>
59	</head>
60	<body>
61	<div class="calc">
62	  <div class="display" data-testid="calc-display" data-value="0" data-error="false" aria-live="polite">0</div>
63	  <div class="keys">
64	    <button class="clear" data-testid="key-clear">AC</button>
65	    <button class="clear" data-testid="key-sign" aria-label="change sign">±</button>
66	    <button class="clear" data-testid="key-percent" aria-label="percent">%</button>
67	    <button class="op" data-testid="key-div" aria-label="divide">÷</button>
68	
69	    <button data-testid="key-7">7</button>
70	    <button data-testid="key-8">8</button>
71	    <button data-testid="key-9">9</button>
72	    <button class="op" data-testid="key-mul" aria-label="multiply">×</button>
73	
74	    <button data-testid="key-4">4</button>
75	    <button data-testid="key-5">5</button>
76	    <button data-testid="key-6">6</button>
77	    <button class="op" data-testid="key-sub" aria-label="subtract">−</button>
78	
79	    <button data-testid="key-1">1</button>
80	    <button data-testid="key-2">2</button>
81	    <button data-testid="key-3">3</button>
82	    <button class="op" data-testid="key-add" aria-label="add">+</button>
83	
84	    <button class="wide" data-testid="key-0">0</button>
85	    <button data-testid="key-dot" aria-label="decimal point">.</button>
86	    <button class="equals" data-testid="key-equals" aria-label="equals">=</button>
87	  </div>
88	</div>
89	<script>
90	(function () {
91	  var display = document.querySelector('[data-testid="calc-display"]');
92	
93	  // entry: string being typed, or null when no entry is in progress.
94	  // value: the number currently shown when not typing (result or stored operand).
95	  // derived: true when entry came from ± or % on a computed number rather than typing;
96	  // it is shown formatted, and the next digit starts a new entry.
97	  var state;
98	
99	  // [REQ-001] [REQ-004]
100	  function reset() {
101	    state = { entry: null, value: 0, stored: null, op: null, error: false, derived: false };
102	  }
103	
104	  // [REQ-001]
105	  function compute(a, op, b) {
106	    var r;
107	    if (op === 'add') r = a + b;
108	    else if (op === 'sub') r = a - b;
109	    else if (op === 'mul') r = a * b;
110	    else if (op === 'div') r = a / b;
111	    // [REQ-003] Division by zero (or any non-finite result) becomes the error state.
112	    // The result is never rounded here: rounding is presentation only.
113	    if (!isFinite(r)) return NaN;
114	    return r;
115	  }
116	
117	  // [REQ-003]
118	  // Presentation only: at most 10 significant digits, no trailing zeros, no
119	  // thousands separators, exponential only for |n| >= 1e10 or |n| < 1e-9.
120	  function formatNumber(n) {
121	    if (n === 0) return '0';
122	    var r = Number(n.toPrecision(10));
123	    var abs = Math.abs(r);
124	    if (abs >= 1e10 || abs < 1e-9) {
125	      return r.toExponential(9).replace(/\.?0+e/, 'e');
126	    }
127	    var exp = parseInt(r.toExponential().split('e')[1], 10);
128	    var s = r.toFixed(Math.max(0, 9 - exp));
129	    return s.indexOf('.') === -1 ? s : s.replace(/\.?0+$/, '');
130	  }
131	
132	  // [REQ-001] [REQ-003]
133	  function render() {
134	    display.setAttribute('data-error', state.error ? 'true' : 'false');
135	    if (state.error) {
136	      display.textContent = 'Error';
137	      display.setAttribute('data-value', String(NaN));
138	      return;
139	    }
140	    if (state.entry !== null) {
141	      display.textContent = state.derived ? formatNumber(Number(state.entry)) : state.entry;
142	      display.setAttribute('data-value', String(Number(state.entry)));
143	    } else {
144	      display.textContent = formatNumber(state.value);
145	      display.setAttribute('data-value', String(state.value));
146	    }
147	  }
148	
149	  // [REQ-001]
150	  function inputDigit(d) {
151	    if (state.derived) { state.entry = null; state.derived = false; }
152	    if (state.entry === null || state.entry === '0') state.entry = d;
153	    else state.entry += d;
154	  }
155	
156	  // [REQ-001]
157	  function inputDot() {
158	    if (state.derived) { state.entry = null; state.derived = false; }
159	    if (state.entry === null) state.entry = '0.';
160	    else if (state.entry.indexOf('.') === -1) state.entry += '.';
161	  }
162	
163	  // [REQ-004]
164	  // ± and % act on the current entry. With no entry in progress, the number on
165	  // the display becomes the entry, so it can still feed the pending operation.
166	  function inputSign() {
167	    if (state.entry === null) { state.entry = String(state.value); state.derived = true; }
168	    state.entry = state.entry.charAt(0) === '-' ? state.entry.slice(1) : '-' + state.entry;
169	  }
170	
171	  // [REQ-004]
172	  function inputPercent() {
173	    var n = state.entry === null ? state.value : Number(state.entry);
174	    state.entry = String(n / 100);
175	    state.derived = true;
176	  }
177	
178	  // [REQ-001] [REQ-002]
179	  // Immediate execution: an operator key first finishes the waiting operation,
180	  // strictly left to right, with no precedence, so the display always shows a
181	  // real running result. 2 + 3 × 4 = 20.
182	  function inputOperator(op) {
183	    if (state.error) return;
184	    if (state.entry !== null) {
185	      var n = Number(state.entry);
186	      state.entry = null;
187	      state.derived = false;
188	      if (state.op !== null && state.stored !== null) {
189	        state.value = compute(state.stored, state.op, n);
190	        if (isNaN(state.value)) { state.error = true; return; }
191	      } else {
192	        state.value = n;
193	      }
194	    }
195	    state.stored = state.value;
196	    state.op = op;
197	  }
198	
199	  // [REQ-001]
200	  function inputEquals() {
201	    if (state.error || state.op === null || state.entry === null) return;
202	    var result = compute(state.stored, state.op, Number(state.entry));
203	    state.entry = null;
204	    state.derived = false;
205	    state.op = null;
206	    state.stored = null;
207	    if (isNaN(result)) { state.error = true; return; }
208	    state.value = result;
209	  }
210	
211	  // [REQ-001] [REQ-003] [REQ-004]
212	  function press(key) {
213	    // In the error state every key except clear is ignored.
214	    if (state.error && key !== 'clear') return;
215	    if (/^[0-9]$/.test(key)) inputDigit(key);
216	    else if (key === 'dot') inputDot();
217	    else if (key === 'sign') inputSign();
218	    else if (key === 'percent') inputPercent();
219	    else if (key === 'add' || key === 'sub' || key === 'mul' || key === 'div') inputOperator(key);
220	    else if (key === 'equals') inputEquals();
221	    else if (key === 'clear') reset();
222	    render();
223	  }
224	
225	  document.querySelector('.keys').addEventListener('click', function (e) {
226	    var btn = e.target.closest('button[data-testid^="key-"]');
227	    if (btn) press(btn.getAttribute('data-testid').slice(4));
228	  });
229	
230	  var keyMap = { '.': 'dot', ',': 'dot', '+': 'add', '-': 'sub', '*': 'mul', 'x': 'mul',
231	    '/': 'div', '%': 'percent', '=': 'equals', 'Enter': 'equals', 'Escape': 'clear', 'c': 'clear', 'C': 'clear' };
232	  document.addEventListener('keydown', function (e) {
233	    if (e.metaKey || e.ctrlKey || e.altKey) return;
234	    var key = /^[0-9]$/.test(e.key) ? e.key : keyMap[e.key];
235	    if (key) {
236	      e.preventDefault();
237	      press(key);
238	    }
239	  });
240	
241	  reset();
242	  render();
243	})();
244	</script>
245	</body>
246	</html>
